import{_ as e,o,c as t,a3 as r}from"./chunks/framework.DMtjdCb-.js";const l="/help/assets/work-detail.ja.BkD0tXmZ.png",n="/help/assets/playback.ja.B0NqSEoO.png",g=JSON.parse('{"title":"5. 再生する","description":"","frontmatter":{},"headers":[],"relativePath":"ja/playback.md","filePath":"ja/playback.md"}'),i={name:"ja/playback.md"};function s(c,a,p,d,h,m){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="_5-再生する" tabindex="-1">5. 再生する <a class="header-anchor" href="#_5-再生する" aria-label="Permalink to &quot;5. 再生する&quot;">​</a></h1><p>利用できる動画がある作品は、詳細画面で話数とプレーヤーを選んで再生します。プレーヤーは操作中の PC・スマートフォンにインストールし、AnimeMachine は NAS 上で動作していても構いません。</p><h2 id="pc-で-1-話再生する" tabindex="-1">PC で 1 話再生する <a class="header-anchor" href="#pc-で-1-話再生する" aria-label="Permalink to &quot;PC で 1 話再生する&quot;">​</a></h2><ol><li>作品詳細の <strong>再生</strong> 欄を開きます。</li><li>複数の再生元や DVD・BD 版がある場合は先に選びます。</li><li>開始する話数を指定し、<strong>PotPlayer で開く</strong> または <strong>VLC で開く</strong> を押します。</li><li>ブラウザーが外部アプリの起動を確認したら許可します。</li></ol><p><img src="'+l+'" alt="再生欄：再生元、版、話数、プレーヤーを選択" loading="lazy"></p><p><strong>確認する状態：</strong> 選んだ話数がプレーヤーで再生されます。複数作品を連続で見る場合は<a href="./continue-watching.html">まとめて続きを再生</a>を使います。</p><h2 id="potplayer-で再生位置を記録する" tabindex="-1">PotPlayer で再生位置を記録する <a class="header-anchor" href="#potplayer-で再生位置を記録する" aria-label="Permalink to &quot;PotPlayer で再生位置を記録する&quot;">​</a></h2><ol><li><strong>再生位置を記録する拡張を導入</strong> から拡張パッケージを取得します。</li><li>PotPlayer を終了し、同梱の <code>README.txt</code> に従って <code>Extension</code> フォルダーをインストール先へ統合します。</li><li>PotPlayer を起動し直し、AnimeMachine から再生します。</li></ol><p>拡張を導入すると正確な位置を保存し、次回は停止位置の 5 秒前から再開します。拡張なしでも再生でき、メディアへのアクセスを基に話数を記録します。記録はリスト生成時のアカウントに対応します。</p><h2 id="毎回ブラウザーの確認が出る" tabindex="-1">毎回ブラウザーの確認が出る <a class="header-anchor" href="#毎回ブラウザーの確認が出る" aria-label="Permalink to &quot;毎回ブラウザーの確認が出る&quot;">​</a></h2><p>Windows の Edge・Chrome では <strong>許可コマンドをコピー</strong> を押し、<code>Win + R</code> で <code>cmd</code> を開きます。コマンドを貼り付けて一度実行し、ブラウザーを開き直します。</p><p><img src="'+n+'" alt="プレーヤーの操作：許可コマンドと位置記録用の拡張" loading="lazy"></p><p>現在の Windows アカウントで、このサイトから PotPlayer と VLC を開くことを許可します。既存の許可は保持されます。自動コピーできない場合は、選択されたコマンド全体を <code>Ctrl+C</code> でコピーして <code>cmd</code> へ貼り付けます。</p><h2 id="スマートフォン・コピーしたアドレス・m3u" tabindex="-1">スマートフォン・コピーしたアドレス・M3U <a class="header-anchor" href="#スマートフォン・コピーしたアドレス・m3u" aria-label="Permalink to &quot;スマートフォン・コピーしたアドレス・M3U&quot;">​</a></h2><p>スマートフォンに VLC を導入し、ブラウザーで <strong>VLC で開く</strong> を押します。リストのアドレスをコピーしてネットワークストリームとして開くか、M3U をダウンロードして開く方法も使えます。</p><p>いずれも生成時のアカウントとの関連を保持します。ただし通常のメディア要求はアクセスした話数を示すもので、<strong>VLC の要求だけでは正確な停止位置を取得できません</strong>。先読みで次の話がアクセスされる場合は、<a href="./continue-watching.html#correct">視聴記録を修正</a>できます。</p><p>リストは生成時点の話数で構成されます。新しい話が追加されたら、AnimeMachine で生成し直してください。</p>',17)])])}const P=e(i,[["render",s]]);export{g as __pageData,P as default};
